import {PortfolioEngine} from './engine.js?v=rig18';
import {DEFAULT_CONFIG,PRESETS,WORLDS,normalizeConfig,validateConfig,clone,escapeHtml as e,safeUrl} from './config.js?v=rig18';
import {t} from './i18n.js?v=rig18';
import {createGameUI} from './game-ui.js?v=rig18';
import {exportPortfolio,downloadBlob,projectJSON,projectName} from './export.js?v=rig18';
const $=s=>document.querySelector(s),DRAFT_KEY='portfolio-studio-draft-v1';
let config=clone(DEFAULT_CONFIG),step=0,storyTab='about',view='avatar',playing=false,engine,gameUI,saveTimer,previewTimer,toastTimer,busy=false;
const thumbnails={presets:{},worlds:{}};
try{const raw=localStorage.getItem(DRAFT_KEY);if(raw)config=normalizeConfig(JSON.parse(raw));}catch{}
const tr=k=>t(config.language,k),isHe=()=>config.language==='he';
function message(text,action){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;if(action){const b=document.createElement('button');b.textContent=isHe()?'ביטול ההסרה':'Undo';b.onclick=()=>{action();el.hidden=true;};el.appendChild(b);}el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,action?9000:5500);}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(DRAFT_KEY,JSON.stringify(config));$('#draftStatus').textContent=tr('draft');}catch{$('#draftStatus').textContent=isHe()?'הטיוטה לא נשמרה':'Draft not saved';message(tr('saveFailed'));}},400);}
function refreshPreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{engine?.update(clone(config));updateCaption();gameUI?.render();},120);persist();}
function heading(title,desc){return `<div class="editor-heading"><span class="editor-kicker">${tr('step')} 0${step+1} / 04</span><h1>${tr(title)}</h1><p>${tr(desc)}</p></div>`;}
function field(key,label,value,{type='text',area=false,required=false,placeholder='',note='',max=12000}={}){const id='f-'+key.replaceAll('.','-');return `<div class="field"><label for="${id}">${tr(label)}${required?` <small>· ${tr('required')}</small>`:''}</label>${area?`<textarea id="${id}" data-field="${key}" dir="auto" maxlength="${max}" ${required?'required':''}>${e(value)}</textarea>`:`<input id="${id}" data-field="${key}" value="${e(value)}" type="${type}" dir="auto" maxlength="${max}" ${required?'required':''} placeholder="${e(placeholder)}">`}${note?`<span class="field-note">${tr(note)}</span>`:''}</div>`;}
function select(key,label,values){return `<div class="field"><label for="a-${key}">${tr(label)}</label><select id="a-${key}" data-avatar="${key}">${values.map(v=>`<option value="${v}" ${config.avatar[key]===v?'selected':''}>${tr(v)}</option>`).join('')}</select></div>`;}
function color(key,label){return `<div class="field"><label for="a-${key}">${tr(label)}</label><div class="color-control"><input id="a-${key}" type="color" value="${config.avatar[key]}" data-avatar="${key}"><span>${config.avatar[key].toUpperCase()}</span></div></div>`;}
function extraIcon(v){const paths={cap:'<path d="M5 13h14l-2-5H7z"/><path d="M4 14c4 2 11 2 16 0"/>',beanie:'<path d="M6 15a6 6 0 0 1 12 0v2H6z"/><path d="M5 17h14"/>',headphones:'<path d="M5 14V11a7 7 0 0 1 14 0v3"/><rect x="3" y="13" width="4" height="6" rx="2"/><rect x="17" y="13" width="4" height="6" rx="2"/>',sunglasses:'<circle cx="8" cy="12" r="3"/><circle cx="16" cy="12" r="3"/><path d="M11 12h2M5 11l-2-1M19 11l2-1"/>',watch:'<rect x="8" y="8" width="8" height="8" rx="2"/><path d="M10 8V5h4v3M10 16v3h4v-3"/>',earrings:'<circle cx="7" cy="13" r="2"/><circle cx="17" cy="13" r="2"/><path d="M7 15v3M17 15v3"/>',chain:'<path d="M6 8c0 10 12 10 12 0M8 8c0 7 8 7 8 0"/><circle cx="12" cy="17" r="2"/>',crossbody:'<path d="M6 5l12 14M8 14h8v5H8z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[v]}</svg>`;}
function characterForm(){if(config.avatar.asset)return heading('charTitle','charDesc')+`<h2 class="form-section-title">${tr('presets')}</h2><div class="preset-grid">${PRESETS.map((p,i)=>`<button class="preset-card ${config.avatar.asset===p.asset?'active':''}" data-preset="${p.id}"><div class="preset-image">${thumbnails.presets[p.id]?`<img src="${thumbnails.presets[p.id]}" alt="">`:`<span>${i+1}</span>`}</div><strong>${tr(p.id)}</strong></button>`).join('')}</div><p class="field-note">${isHe()?'דמות KayKit עם לבוש מקורי ואנימציות מוכנות. בדקו עמידה, הליכה וריצה בפאנל התנועה. אפשרויות התאמת הגוף והאקססוריז זמינות בארבע הדמויות המקוריות.':'KayKit character with original outfit and authored animations. Try standing, walking and running in the motion panel. Body and accessory customization is available for the original four characters.'}</p><p class="field-note">Kay Lousberg · CC0</p>`;return heading('charTitle','charDesc')+`<h2 class="form-section-title">${tr('presets')}</h2><div class="preset-grid">${PRESETS.map((p,i)=>`<button class="preset-card ${config.avatar.id===p.id?'active':''}" data-preset="${p.id}" aria-pressed="${config.avatar.id===p.id}"><div class="preset-image">${thumbnails.presets[p.id]?`<img src="${thumbnails.presets[p.id]}" alt="">`:`<span>0${i+1}</span>`}</div><strong>${tr(p.id)}</strong></button>`).join('')}</div><h2 class="form-section-title">${tr('appearance')}</h2>${select('model','model',['male','female'])}<div class="field"><span class="field-label">${tr('body')}</span><div class="choice-pills">${['slim','regular','athletic'].map(v=>`<button data-body="${v}" class="${config.avatar.body===v?'active':''}" aria-pressed="${config.avatar.body===v}">${tr(v)}</button>`).join('')}</div></div><div class="field"><span class="field-label">${tr('skin')}</span><div class="swatches">${['#f1cfb5','#e8bb9d','#d3a17f','#bd8f73','#9c6b50','#80533f','#593c32'].map(v=>`<button class="swatch ${config.avatar.skin===v?'active':''}" data-skin="${v}" style="--swatch:${v}" aria-label="${tr('skin')} ${v}" aria-pressed="${config.avatar.skin===v}"></button>`).join('')}</div></div><div class="two-fields">${color('accessoryColor','accessoryColor')}</div><div class="two-fields">${select('hair','hair',['crop','none'])}${color('hairColor','hairColor')}</div><h2 class="form-section-title">${tr('wardrobe')}</h2><div class="two-fields">${select('outfit','outfit',config.avatar.model==='female'?['tshirt','hoodie']:['tshirt','longsleeve','jacket'])}${color('top','topColor')}</div><div class="two-fields">${color('pants','pantsColor')}${color('shoes','shoeColor')}</div><div class="two-fields">${select('accessory','accessory',['none','glasses','backpack','both'])}</div><h2 class="form-section-title">${tr('extras')}</h2><div class="extras-grid">${['cap','beanie','headphones','sunglasses','watch','earrings','chain','crossbody'].map(v=>`<label class="extra-choice"><input type="checkbox" data-extra="${v}" ${config.avatar.extras?.includes(v)?'checked':''}><span class="extra-icon">${extraIcon(v)}</span><span>${tr(v)}</span></label>`).join('')}</div>`;}
function recordFields(kind,row,index){const base=`${kind}.${index}.`;if(kind==='skills')return field(base+'name','skillGroup',row.name,{required:true,max:120})+field(base+'items','skillItems',row.items,{area:true});if(kind==='experience')return field(base+'role','role',row.role,{required:true,max:150})+field(base+'company','company',row.company,{max:150})+`<div class="two-fields">${field(base+'start','start',row.start,{max:60})}${field(base+'end','end',row.end,{max:60})}</div>`+field(base+'description','description',row.description,{area:true,note:'bulletHint'});if(kind==='education')return field(base+'degree','degree',row.degree,{required:true,max:180})+field(base+'school','school',row.school,{max:180})+`<div class="two-fields">${field(base+'start','start',row.start,{max:60})}${field(base+'end','end',row.end,{max:60})}</div>`+field(base+'description','description',row.description,{area:true});return field(base+'name','projectName',row.name,{required:true,max:150})+field(base+'summary','summary',row.summary,{area:true})+field(base+'stack','stack',row.stack)+field(base+'url','url',row.url,{type:'url',placeholder:'https://'});}
function storyForm(){let content='';const p=config.profile;
 if(storyTab==='about')content=field('profile.name','name',p.name,{required:true,max:120})+field('profile.role','role',p.role,{required:true,max:120})+field('profile.introduction','introduction',p.introduction,{area:true,required:true})+field('profile.location','location',p.location,{max:120})+`<label class="checkbox-field"><input type="checkbox" id="sampleToggle" ${config.isSample?'checked':''}><span>${tr('sampleToggle')}</span></label>`;
 else if(storyTab==='contact')content=field('profile.email','email',p.email,{type:'email',placeholder:'you@example.com'})+field('profile.website','website',p.website,{type:'url',placeholder:'https://'})+field('profile.linkedin','linkedin',p.linkedin,{type:'url',placeholder:'https://linkedin.com/in/…'})+field('profile.github','github',p.github,{type:'url',placeholder:'https://github.com/…'})+field('profile.languages','languages',p.languages,{area:true})+field('profile.certifications','certifications',p.certifications,{area:true});
 else {const rows=config[storyTab];content=(rows.length?rows.map((r,i)=>`<article class="entry-card"><div class="entry-top"><span class="entry-title">${tr(storyTab)} · ${String(i+1).padStart(2,'0')}</span><div class="entry-actions"><button data-reorder="${i},-1" ${i===0?'disabled':''} aria-label="${isHe()?'העברה למעלה':'Move up'}">↑</button><button data-reorder="${i},1" ${i===rows.length-1?'disabled':''} aria-label="${isHe()?'העברה למטה':'Move down'}">↓</button><button class="remove-entry" data-remove="${i}" aria-label="${tr('remove')}">✕</button></div></div>${recordFields(storyTab,r,i)}</article>`).join(''):`<div class="empty-state">${tr('empty')}</div>`)+`<button class="add-button" id="addEntry" ${rows.length>=20?'disabled':''}>＋ ${tr('add')}</button>`;}
 return heading('storyTitle','storyDesc')+`<nav class="story-tabs" aria-label="${tr('story')}">${['about','experience','skills','education','projects','contact'].map(k=>`<button data-story="${k}" class="${storyTab===k?'active':''}" aria-pressed="${storyTab===k}">${tr(k)}</button>`).join('')}</nav>${config.isSample?`<div class="sample-note">${tr('sample')}</div>`:''}${content}<p class="privacy-note">${tr('localNote')}</p>`;
}
function worldForm(){return heading('worldTitle','worldDesc')+`<div class="world-list">${WORLDS.map((w,i)=>`<button class="world-card ${config.world===w.id?'active':''}" data-world="${w.id}" aria-pressed="${config.world===w.id}" style="--world-sky:${w.sky}"><div class="world-image">${thumbnails.worlds[w.id]?`<img src="${thumbnails.worlds[w.id]}" alt="">`:`<span>0${i+1}</span>`}</div>${config.world===w.id?`<span class="selected-badge">✓ ${tr('selected')}</span>`:''}<div class="world-description"><h3>${tr('world_'+w.id)}</h3><p>${tr('desc_'+w.id)}</p></div></button>`).join('')}</div>`;}
function errors(){const list=validateConfig(config);if(!isHe())return list;return list.map(s=>s.replace('Your name is required.','יש למלא שם מלא.').replace('Professional title is required.','יש למלא כותרת מקצועית.').replace('Introduction is required.','יש להוסיף טקסט היכרות.').replace(/Add a title to (.+) (\d+), or remove the empty entry\./,(_,type,n)=>`יש להשלים כותרת לרשומה ${n} (${({'skill group':'כישורים',experience:'ניסיון',education:'השכלה',project:'פרויקט'})[type]||type}), או להסיר אותה.`).replace(/(.+) must be a complete https:\/\/ or http:\/\/ URL\./,(_,label)=>`יש להזין כתובת מלאה המתחילה ב־https:// או http:// בשדה ${({'Website':'אתר אישי','LinkedIn':'LinkedIn','GitHub':'GitHub'})[label]||'קישור לפרויקט'}.`).replace('Enter a valid email address, or leave it blank.','יש להזין כתובת דוא״ל תקינה או להשאיר את השדה ריק.'));}
function exportForm(){const issues=errors(),total=['experience','skills','education','projects'].reduce((sum,k)=>sum+config[k].length,0);return heading('exportTitle','exportDesc')+`<div class="export-summary"><div class="export-checkmark">${issues.length?'!':'✓'}</div><h3 dir="auto">${e(config.profile.name||tr('renameProject'))}</h3><p dir="auto">${e(config.profile.role)}</p><p>${tr('world_'+config.world)}</p></div><h2 class="form-section-title">${tr('checks')}</h2><ul class="checklist"><li><span>${config.profile.name.trim()&&config.profile.role.trim()?'✓':'○'}</span>${tr('checkName')}</li><li><span>${config.profile.introduction.trim()?'✓':'○'}</span>${tr('checkIntro')}</li><li><span>✓</span>${tr('checkWorld')}</li><li><span>✓</span>${tr('checkContent')}<b>${total}</b></li></ul>${issues.length?`<div class="validation-box"><strong>${tr('validation')}</strong><ul>${issues.map(s=>`<li>${e(s)}</li>`).join('')}</ul></div>`:''}<div class="export-actions"><button class="export-download primary" data-export="html" ${issues.length||busy?'disabled':''}><span class="download-icon">↓</span><span><strong>${tr('downloadHtml')}</strong><small>${tr('htmlInfo')}</small></span></button><button class="export-download" data-export="zip" ${issues.length||busy?'disabled':''}><span class="download-icon">▣</span><span><strong>${tr('downloadZip')}</strong><small>${tr('zipInfo')}</small></span></button><button class="export-download" id="saveEditable"><span class="download-icon">◇</span><span><strong>${tr('saveEditable')}</strong><small>${tr('jsonInfo')}</small></span></button></div><p class="privacy-note">${tr('privacy')}</p><p class="privacy-note">${tr('localNote')}</p>`;}
function renderShowroom(){
 document.querySelector('.studio-workspace').classList.toggle('character-layout',step===0);
 document.querySelector('.showroom-tools')?.remove();
 if(step!==0)return;
 const panel=document.createElement('aside');panel.className='showroom-tools';
 panel.innerHTML=`<span class="editor-kicker">AVATAR LAB / 01</span><h2>${isHe()?'תצוגת הדמות':'Character view'}</h2><p>${isHe()?'בחרו זווית ובדקו את המראה מכל צד.':'Choose an angle and inspect your look.'}</p><div class="showroom-angles">${[['front','◉',isHe()?'חזית':'Front'],['side','◐',isHe()?'צד':'Side'],['back','◎',isHe()?'גב':'Back'],['face','⊕',isHe()?'תקריב':'Close-up']].map(([id,icon,label])=>`<button data-angle="${id}"><b>${icon}</b>${label}</button>`).join('')}</div><div class="showroom-divider"></div><h2>${isHe()?'בדיקת תנועה':'Motion preview'}</h2><div class="showroom-motion">${[['idle',isHe()?'עמידה':'Standing'],['walk',isHe()?'הליכה':'Walking'],['run',isHe()?'ריצה':'Running']].map(([id,label])=>`<button data-motion="${id}" aria-pressed="${(engine?.previewMotion||'idle')===id}">${label}</button>`).join('')}</div><p class="showroom-hint">${tr('rotate')}</p>`;
 document.querySelector('.studio-workspace').append(panel);
 panel.querySelectorAll('[data-angle]').forEach(b=>b.onclick=()=>{if(!engine)return;setView('avatar');engine.orbit={front:0,side:Math.PI/2,back:Math.PI,face:0}[b.dataset.angle];engine.distance=b.dataset.angle==='face'?.7:1;});
 panel.querySelectorAll('[data-motion]').forEach(b=>b.onclick=()=>{if(!engine)return;engine.previewMotion=b.dataset.motion;panel.querySelectorAll('[data-motion]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
}
function renderEditor({resetScroll=false}={}){renderShowroom();const node=$('#editor'),old=node.scrollTop;node.innerHTML=[characterForm,storyForm,worldForm,exportForm][step]();node.scrollTop=resetScroll?0:old;bindEditor();}
function renderChrome(){document.documentElement.lang=config.language;document.documentElement.dir=isHe()?'rtl':'ltr';document.title=isHe()?'Portfolio Studio · בונים עולם לסיפור שלכם':'Portfolio Studio · Your story, playable';$('#language').value=config.language;$('#brandTagline').textContent=tr('tagline');$('#draftStatus').textContent=tr('draft');$('#saveProject').textContent='↓ '+tr('saveProject');$('#loadProject').textContent=tr('loadProject');$('#steps').setAttribute('aria-label',isHe()?'שלבי יצירה':'Creation steps');$('#steps').innerHTML=['character','story','world','export'].map((k,i)=>`<button class="step-button ${step===i?'active':step>i?'done':''}" data-step="${i}" ${step===i?'aria-current="step"':''}><span class="step-number">${String(i+1).padStart(2,'0')}</span><span>${tr(k)}</span></button>`).join('');$('#steps').querySelectorAll('button').forEach(b=>b.onclick=()=>goStep(Number(b.dataset.step)));$('#previous').textContent=(isHe()?'→ ':'← ')+tr('back');$('#previous').disabled=step===0;$('#next').textContent=step===3?tr('play'):tr('next')+(isHe()?' ←':' →');$('#stepCount').textContent=`0${step+1} / 04`;$('#liveLabel').textContent=tr('live');document.querySelector('[data-view="avatar"]').textContent=tr('avatarView');document.querySelector('[data-view="world"]').textContent=tr('worldView');$('#playPreview').textContent=tr('play');$('#exitPlay').textContent='✕ '+tr('exitPlay');$('#rotateHint').textContent=tr('rotate');$('#resetView').setAttribute('aria-label',tr('resetView'));$('#studioCanvas').setAttribute('aria-label',tr('rotate'));updateCaption();}
function updateCaption(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#previewKicker').textContent=view==='avatar'?tr('character'):tr('world');$('#previewName').textContent=view==='avatar'?config.profile.name:tr('world_'+config.world);$('#previewRole').textContent=view==='avatar'?config.profile.role:tr('desc_'+config.world);}
function goStep(n){step=Math.max(0,Math.min(3,n));if(step===0)setView('avatar');if(step>=2)setView('world');renderChrome();renderEditor({resetScroll:true});}
function setView(mode){view=mode;if(!playing)engine?.setMode(mode);updateCaption();}
function play(){if(!engine){message(tr('graphicsError'));return;}playing=true;$('#preview').classList.add('playing');$('#exitPlay').hidden=false;engine.setMode('play');gameUI.setVisible(true);gameUI.render();engine.resize();$('#studioCanvas').focus();}
function exitPlay(){playing=false;$('#preview').classList.remove('playing');$('#exitPlay').hidden=true;gameUI?.setVisible(false);engine?.setMode(view);engine?.resize();$('#playPreview').focus();}
function saveProject(){downloadBlob(new Blob([projectJSON(config)],{type:'application/json'}),projectName(config)+'.json');message(tr('downloaded'));}
function bindEditor(){
 $('#editor').querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{config.avatar=clone(PRESETS.find(p=>p.id===b.dataset.preset));renderEditor();refreshPreview();});
 $('#editor').querySelectorAll('[data-extra]').forEach(input=>input.addEventListener('change',()=>{const extras=new Set(config.avatar.extras||[]);if(input.checked)extras.add(input.dataset.extra);else extras.delete(input.dataset.extra);if(input.checked&&['cap','beanie'].includes(input.dataset.extra)){const other=input.dataset.extra==='cap'?'beanie':'cap';extras.delete(other);$('#editor').querySelector(`[data-extra="${other}"]`).checked=false;}config.avatar.extras=[...extras];config.avatar.id='custom';refreshPreview();}));
 $('#editor').querySelectorAll('[data-avatar]').forEach(input=>input.addEventListener('input',()=>{config.avatar[input.dataset.avatar]=input.value;if(input.dataset.avatar==='model'){config=normalizeConfig(config);renderEditor();}config.avatar.id='custom';if(input.type==='color')input.nextElementSibling.textContent=input.value.toUpperCase();$('#editor').querySelectorAll('.preset-card').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});refreshPreview();}));
 $('#editor').querySelectorAll('[data-body],[data-skin]').forEach(b=>b.onclick=()=>{if(b.dataset.body)config.avatar.body=b.dataset.body;if(b.dataset.skin)config.avatar.skin=b.dataset.skin;config.avatar.id='custom';renderEditor();refreshPreview();});
 $('#editor').querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{storyTab=b.dataset.story;renderEditor({resetScroll:true});});
 $('#editor').querySelectorAll('[data-field]').forEach(input=>input.addEventListener('input',()=>{const path=input.dataset.field.split('.');let target=config;for(const key of path.slice(0,-1))target=target[key];target[path.at(-1)]=input.value;refreshPreview();}));
 $('#sampleToggle')?.addEventListener('change',ev=>{config.isSample=ev.target.checked;refreshPreview();});
 $('#addEntry')?.addEventListener('click',()=>{const fields={skills:['name','items'],experience:['role','company','start','end','description'],education:['degree','school','start','end','description'],projects:['name','summary','stack','url']}[storyTab];if(config[storyTab].length>=20)return;config[storyTab].push(Object.fromEntries(fields.map(k=>[k,''])));renderEditor();persist();const cards=$('#editor').querySelectorAll('.entry-card');cards[cards.length-1]?.scrollIntoView({block:'nearest'});cards[cards.length-1]?.querySelector('input')?.focus();refreshPreview();});
 $('#editor').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const key=storyTab,index=Number(b.dataset.remove),[removed]=config[key].splice(index,1);renderEditor();refreshPreview();message(isHe()?'הרשומה הוסרה.':'Entry removed.',()=>{config[key].splice(index,0,removed);if(step===1&&storyTab===key)renderEditor();refreshPreview();});});
 $('#editor').querySelectorAll('[data-reorder]').forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.reorder.split(',').map(Number),rows=config[storyTab];[rows[i],rows[i+d]]=[rows[i+d],rows[i]];renderEditor();refreshPreview();});
 $('#editor').querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{config.world=b.dataset.world;renderEditor();refreshPreview();});
 $('#editor').querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>doExport(b.dataset.export));$('#saveEditable')?.addEventListener('click',saveProject);
}
async function doExport(format){if(busy)return;const issues=errors();if(issues.length){step=3;renderChrome();renderEditor();message(tr('validation'));return;}busy=true;if(step===3)renderEditor();message(tr('saving'));try{await exportPortfolio(clone(config),format);message(tr('downloaded'));}catch(error){console.error(error);message(tr('exportError'));}finally{busy=false;if(step===3)renderEditor();}}
$('#previous').onclick=()=>goStep(step-1);$('#next').onclick=()=>step===3?play():goStep(step+1);$('#saveProject').onclick=saveProject;$('#loadProject').onclick=()=>$('#projectFile').click();$('#playPreview').onclick=play;$('#exitPlay').onclick=exitPlay;$('#resetView').onclick=()=>engine?.setMode(view);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('#language').onchange=ev=>{config.language=ev.target.value;renderChrome();renderEditor();refreshPreview();};
$('#projectFile').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('Project file too large');const imported=normalizeConfig(JSON.parse(await file.text()));config=imported;renderChrome();renderEditor({resetScroll:true});refreshPreview();message(tr('imported'));}catch(error){message(tr('importFailed')+' '+(isHe()?'בחרו קובץ פרויקט תקין של המערכת.':error.message));}finally{ev.target.value='';}};
renderChrome();renderEditor();
try{engine=new PortfolioEngine($('#studioCanvas'),clone(config),{mode:view,onError:()=>{$('#previewError').textContent=tr('graphicsError');$('#previewError').hidden=false;}});gameUI=createGameUI($('#preview'),engine,()=>config);gameUI.setVisible(false);}catch(error){console.error(error);$('#previewError').textContent=tr('graphicsError');$('#previewError').hidden=false;}
async function thumbnailsTask(){if(!engine)return;const canvas=document.createElement('canvas');let temp;try{temp=new PortfolioEngine(canvas,clone(config),{mode:'avatar',capture:true,animate:false,width:240,height:280});for(const p of PRESETS){temp.update({...clone(config),avatar:clone(p)});temp.setMode('avatar');temp.resize(240,280);await temp.avatar.ready;thumbnails.presets[p.id]=temp.capture();await new Promise(requestAnimationFrame);}for(const w of WORLDS){temp.update({...clone(config),world:w.id});temp.setMode('world');temp.resize(420,240);thumbnails.worlds[w.id]=temp.capture();await new Promise(requestAnimationFrame);}if(step===0||step===2)renderEditor();}catch(error){console.warn('Preview thumbnails unavailable',error);}finally{temp?.dispose();}}
setTimeout(thumbnailsTask,500);
window.addEventListener('pagehide',()=>{try{localStorage.setItem(DRAFT_KEY,JSON.stringify(config));}catch{};});
// Optional WebMCP support shares the editor's real state and validation.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'get_portfolio_state',description:'Read the current editable portfolio, selected world, character and validation issues.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({config:clone(config),step,issues:errors()})});
 register({name:'update_portfolio_profile',description:'Update résumé profile fields in the visible editor. This changes the local browser draft, not a published portfolio.',inputSchema:{type:'object',properties:{profile:{type:'object',properties:Object.fromEntries(Object.keys(DEFAULT_CONFIG.profile).map(k=>[k,{type:'string',maxLength:12000}])),additionalProperties:false}},required:['profile'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input?.profile||typeof input.profile!=='object'||Array.isArray(input.profile)||Object.entries(input.profile).some(([k,v])=>!(k in DEFAULT_CONFIG.profile)||typeof v!=='string'))throw Error('Invalid profile fields');config=normalizeConfig({...config,profile:{...config.profile,...input.profile}});step=1;storyTab='about';renderChrome();renderEditor();refreshPreview();return {profile:clone(config.profile),issues:errors()};}});
 register({name:'choose_portfolio_world',description:'Select one of the five 3D worlds and show it in the live preview.',inputSchema:{type:'object',properties:{world:{type:'string',enum:WORLDS.map(w=>w.id)}},required:['world'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!WORLDS.some(w=>w.id===input?.world))throw Error('Unknown world');config.world=input.world;step=2;view='world';engine?.update(clone(config));engine?.setMode(view);renderChrome();renderEditor();persist();return {world:config.world};}});
 register({name:'download_portfolio',description:'Validate and download the current portfolio as a playable HTML file or website ZIP, including entered résumé details.',inputSchema:{type:'object',properties:{format:{type:'string',enum:['html','zip']}},required:['format'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!['html','zip'].includes(input?.format))throw Error('Unknown format');if(errors().length)throw Error(errors().join(' '));await exportPortfolio(clone(config),input.format);return {downloadStarted:true,format:input.format};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
